<script setup lang="ts">
import { computed, onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { http } from "@/utils/http";
type Row = Record<string, unknown>; const route = useRoute(); const rows = ref<Row[]>([]); const devices = ref<Row[]>([]); const loading = ref(false); const error = ref(""); const length = ref(20); const generated = ref(""); const unlocked = ref(false); const search = ref(""); const folder = ref("all"); const selected = ref<Row | null>(null); const page = computed(() => String(route.path.split("/").pop())); const title = computed(() => ({ passwords: "密码保险库", generator: "密码生成器", health: "密码健康", devices: "密码设备" }[page.value] || "密码管理")); const visibleRows = computed(() => rows.value.filter(row => !search.value || String(row.name || row.title || "").toLowerCase().includes(search.value.toLowerCase())));
async function load() { if (page.value === "passwords" && !unlocked.value) return; loading.value = true; error.value = ""; try { if (page.value === "devices") { const r = await http.get<unknown, unknown>("/password/devices"); devices.value = Array.isArray(r) ? r as Row[] : []; } else { const r = await http.get<unknown, unknown>("/password/vaults"); rows.value = Array.isArray(r) ? r as Row[] : []; } } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "密码数据加载失败"; } finally { loading.value = false; } }
async function unlock() { unlocked.value = true; await load(); } function lock() { unlocked.value = false; rows.value = []; selected.value = null; }
async function generate() { try { const r = await http.post<unknown, unknown>("/password/generator/password", { data: { length: length.value } }); generated.value = String((r as Row)?.value || (r as Row)?.secret || "已生成（仅当前页面显示）"); } catch { error.value = "生成器接口暂不可用"; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">{{ title }}</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">敏感字段默认不显示，解锁和导出遵循密码保险库安全策略。</p></div><div class="flex gap-2"><el-button v-if="page === 'passwords' && unlocked" @click="lock">立即锁定</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-card v-if="page === 'passwords' && !unlocked" shadow="never" class="max-w-xl"><div class="text-lg font-medium">密码保险库已锁定</div><p class="mt-2 text-sm text-[var(--el-text-color-secondary)]">解锁前不会展示条目数量、标题、用户名或健康状态。</p><el-button type="primary" class="mt-5" @click="unlock">解锁密码保险库</el-button></el-card><el-card v-else-if="page === 'generator'" shadow="never"><el-form inline><el-form-item label="长度"><el-input-number v-model="length" :min="8" :max="128"/></el-form-item><el-button type="primary" @click="generate">生成密码</el-button></el-form><el-alert v-if="generated" :title="generated" type="success" show-icon class="mt-4"/></el-card><div v-else-if="page === 'passwords'" class="grid grid-cols-1 gap-4 lg:grid-cols-[220px_minmax(0,1fr)_320px]"><el-card shadow="never"><template #header>Folder / 类型</template><el-radio-group v-model="folder" class="flex flex-col items-start gap-3"><el-radio value="all">全部条目</el-radio><el-radio value="favorite">收藏</el-radio><el-radio value="login">Login</el-radio><el-radio value="note">Secure Note</el-radio><el-radio value="key">API Key / SSH</el-radio></el-radio-group></el-card><el-card shadow="never"><template #header><div class="flex items-center justify-between"><el-input v-model="search" clearable placeholder="仅搜索已解锁保险库" class="w-64"/><el-button type="primary" plain>新建条目</el-button></div></template><el-empty v-if="!visibleRows.length" description="暂无条目"/><div v-for="row in visibleRows" :key="String(row.id)" class="flex items-center justify-between border-b py-3 last:border-0" @click="selected = row"><div><div class="font-medium">{{ row.name || row.title || '未命名条目' }}</div><div class="text-xs text-[var(--el-text-color-secondary)]">{{ row.username || '用户名已遮罩' }} · {{ row.updatedAt || '—' }}</div></div><el-tag size="small">{{ row.healthStatus || '未检查' }}</el-tag></div></el-card><el-card shadow="never"><template #header>条目详情</template><el-empty v-if="!selected" description="选择一个条目"/><el-descriptions v-else :column="1" border><el-descriptions-item label="标题">{{ selected.name || selected.title }}</el-descriptions-item><el-descriptions-item label="类型">{{ selected.type || 'Login' }}</el-descriptions-item><el-descriptions-item label="用户名">{{ selected.username || '已遮罩' }}</el-descriptions-item><el-descriptions-item label="密码">•••••••• <el-button link>显示</el-button></el-descriptions-item><el-descriptions-item label="URL">{{ selected.url || '—' }}</el-descriptions-item></el-descriptions></el-card></div><el-card v-else shadow="never"><el-empty v-if="page === 'devices' ? !devices.length : !rows.length" :description="page === 'devices' ? '暂无已授权设备' : '暂无数据或保险库尚未解锁'"/><el-table v-else :data="page === 'devices' ? devices : rows" stripe><el-table-column prop="id" label="技术标识" min-width="240"/><el-table-column prop="name" label="名称" min-width="180"/><el-table-column prop="status" label="状态" width="140"/><el-table-column prop="securityProfile" label="安全策略" min-width="160"/><el-table-column prop="lastSeenAt" label="最近同步" min-width="180"/></el-table></el-card></main></template>
